package dev.quinton.goa.core.game.puzzles

import dev.quinton.goa.core.game.engine.GameEngine

/**
 * A puzzle's precomputed answers on every winning line (ENCODING.md "Answer keys"): at each player
 * decision the options that keep the goal forced, at each other decision the reply the runtime plays.
 * Lines are keyed by the option indices answered since the start (`""` = the first decision). With a
 * key the runtime needs no search while the player stays on a winning line; off the key (after a
 * miss) it searches with a small budget. Generated by the solver and checked by `PuzzleBookTest`,
 * which rewrites a stale key file and fails, so the key is always the solver's own answer.
 */
class AnswerKey(
    val puzzleId: String,
    val engineVersion: Int,
    /** [fingerprint] of the starting position the key was made for. */
    val fingerprint: String,
    val entries: Map<String, Entry>,
) {
    sealed interface Entry

    /** A player decision: the option indices that keep the goal forced (ascending, never empty). */
    data class Wins(val options: List<Int>) : Entry

    /** Any other decision: the option index the runtime answers. */
    data class Reply(val option: Int) : Entry

    fun format(): String = buildString {
        append("# Answer key of $puzzleId: generated by PuzzleBookTest from the solver; do not edit.\n")
        append("puzzle $puzzleId\n")
        append("engine $engineVersion\n")
        append("root $fingerprint\n")
        for ((path, e) in entries.toSortedMap(PATH_ORDER)) {
            val p = path.ifEmpty { ROOT }
            when (e) {
                is Wins -> append("P $p ${e.options.joinToString(",")}\n")
                is Reply -> append("R $p ${e.option}\n")
            }
        }
    }

    override fun equals(other: Any?): Boolean = other is AnswerKey && other.format() == format()

    override fun hashCode(): Int = format().hashCode()

    companion object {
        private const val ROOT = "-"

        /** Shortest lines first, then by their indices. */
        private val PATH_ORDER: Comparator<String> = compareBy<String>({
            it.count { c -> c == '.' } +
                if (it.isEmpty()) 0 else 1
        }, { it })

        /** Where key files live on the classpath (`src/main/resources/` + this). */
        const val RESOURCE_DIR: String = "dev/quinton/goa/core/game/puzzles/keys"

        fun pathOf(indices: List<Int>): String = indices.joinToString(".")

        /** Identifies a starting position: the engine checkpoint and the answers inside its step. */
        fun fingerprint(node: Node): String {
            val seg = node.session.stepAnswers.joinToString("|").hashCode()
            return "%016x%016x%08x".format(node.checkpointHash, node.checkpointHash2, seg)
        }

        fun parse(text: String): AnswerKey {
            var id = ""
            var version = -1
            var root = ""
            val entries = LinkedHashMap<String, Entry>()
            for (raw in text.lineSequence()) {
                val line = raw.trim()
                if (line.isEmpty() || line.startsWith("#")) continue
                val parts = line.split(" ")
                when (parts[0]) {
                    "puzzle" -> id = parts[1]

                    "engine" -> version = parts[1].toInt()

                    "root" -> root = parts[1]

                    "P", "R" -> {
                        val path = if (parts[1] == ROOT) "" else parts[1]
                        entries[path] = if (parts[0] == "P") {
                            Wins(parts[2].split(",").map { it.toInt() })
                        } else {
                            Reply(parts[2].toInt())
                        }
                    }

                    else -> error("Bad answer key line: $line")
                }
            }
            return AnswerKey(id, version, root, entries)
        }

        /** The stored key of [puzzleId], if there is one on the classpath. */
        fun load(puzzleId: String): AnswerKey? =
            AnswerKey::class.java.classLoader?.getResourceAsStream("$RESOURCE_DIR/$puzzleId.key")
                ?.bufferedReader()?.use { parse(it.readText()) }

        /**
         * Builds the key of [prepared] by solving every option at every player decision of every
         * winning line. Fails when the goal is not forced, when a solve runs out of budget, or past
         * [maxEntries] decisions (the puzzle then has too many alternative lines: tighten it).
         */
        fun generate(prepared: PreparedPuzzle, maxEntries: Int = MAX_ENTRIES): AnswerKey {
            val solver = prepared.solver
            val entries = LinkedHashMap<String, Entry>()
            fun visit(n: Node, path: List<Int>) {
                val d = n.decision ?: return
                if (n.progress.state != GoalState.OPEN) return
                check(entries.size < maxEntries) {
                    "${prepared.info.id}: more than $maxEntries decisions on winning lines"
                }
                if (solver.sideOf(d) == Side.PLAYER) {
                    val wins = ArrayList<Int>()
                    for (i in d.options.indices) {
                        val c = checkNotNull(solver.child(n, d.options[i]))
                        val v = solver.solve(c).value
                        check(v != Value.UNKNOWN) { "${prepared.info.id}: out of budget at ${pathOf(path + i)}" }
                        if (v == Value.WIN) wins += i
                    }
                    check(wins.isNotEmpty()) { "${prepared.info.id}: no winning option at '${pathOf(path)}'" }
                    entries[pathOf(path)] = Wins(wins)
                    for (i in wins) visit(solver.child(n, d.options[i])!!, path + i)
                } else {
                    val s = solver.solve(n)
                    check(s.value == Value.WIN) { "${prepared.info.id}: ${s.value} at '${pathOf(path)}'" }
                    entries[pathOf(path)] = Reply(s.best)
                    visit(solver.child(n, d.options[s.best])!!, path + s.best)
                }
            }
            visit(prepared.rootNode, emptyList())
            return AnswerKey(prepared.info.id, GameEngine.ENGINE_VERSION, fingerprint(prepared.rootNode), entries)
        }

        const val MAX_ENTRIES: Int = 20_000
    }
}
